/**
 * Modeled loosely on `ICatalogClassItem` in Berkeleytime's real catalog
 * module (apps/backend/src/modules/catalog/catalog-cache.ts). A trimmed-down
 * shape is enough for this exercise -- the point isn't the schema, it's who
 * is allowed to be the source of truth for it.
 */
export interface ClassRecord {
  /** e.g. "COMPSCI-61A-001" -- subject, course number, section, dash-joined. */
  classId: string;
  subject: string;
  courseNumber: string;
  section: string;
  title: string;
  units: number;
  instructor: string;
}
